def twoCitySchedCost(costs: list[list[int]]) -> int:
    # Sort by differential: costA - costB
    costs.sort(key=lambda x: x[0] - x[1])
    n = len(costs) // 2
    return sum(costs[i][0] for i in range(n)) + sum(costs[i][1] for i in range(n, 2 * n))

